def _polish_g7_a1_4(lesson):
    """Hand-audited lesson on Euclidean division and divisibility."""
    if lesson["id"] != "g7-a1-4":
        return

    lesson["theory"] = [
        "Για φυσικούς αριθμούς $\\Delta$ και $\\delta$, με $\\delta\\ne0$, υπάρχουν μοναδικοί φυσικοί $\\pi$ και $\\upsilon$ ώστε $\\Delta=\\delta\\cdot\\pi+\\upsilon$ και $0\\le\\upsilon<\\delta$.",
        "Ο $\\Delta$ λέγεται διαιρετέος, ο $\\delta$ διαιρέτης, ο $\\pi$ πηλίκο και ο $\\upsilon$ υπόλοιπο.",
        "Η συνθήκη $0\\le\\upsilon<\\delta$ είναι απαραίτητη. Για παράδειγμα, η ισότητα $29=6\\cdot4+5$ εκφράζει Ευκλείδεια διαίρεση με διαιρέτη $6$.",
        "Αν $\\upsilon=0$, η διαίρεση είναι τέλεια. Τότε ο $\\delta$ διαιρεί τον $\\Delta$, ο $\\delta$ είναι διαιρέτης του $\\Delta$ και ο $\\Delta$ είναι πολλαπλάσιο του $\\delta$.",
        "Ο διαιρέτης δεν μπορεί να είναι $0$. Ισχύουν επίσης $\\Delta:\\Delta=1$ για $\\Delta\\ne0$, $\\Delta:1=\\Delta$ και $0:\\delta=0$ για $\\delta\\ne0$.",
        "Η δοκιμή της διαίρεσης γίνεται ελέγχοντας συγχρόνως τη σχέση $\\Delta=\\delta\\cdot\\pi+\\upsilon$ και την ανισότητα $0\\le\\upsilon<\\delta$.",
    ]
    lesson["example"] = {"title": "Λυμένο παράδειγμα: Οργάνωση μαθητών σε ομάδες", "text": "$168$ μαθητές χωρίζονται σε ομάδες των $5$. Έχουμε $168=5\\cdot33+3$, με $0\\le3<5$. Άρα σχηματίζονται $33$ πλήρεις πεντάδες και περισσεύουν $3$ μαθητές. Επειδή το υπόλοιπο δεν είναι $0$, το $5$ δεν διαιρεί το $168$."}
    lesson["plan"].update({
        "objectives": ["Να αναγνωρίζει διαιρετέο, διαιρέτη, πηλίκο και υπόλοιπο.", "Να εκτελεί και να επαληθεύει Ευκλείδεια διαίρεση με τις δύο αναγκαίες συνθήκες.", "Να συνδέει την τέλεια διαίρεση με τις έννοιες διαιρέτης και πολλαπλάσιο.", "Να ερμηνεύει πηλίκο και υπόλοιπο σε προβλήματα μοιρασμού και συσκευασίας."],
        "materials": ["Μετρητές ή καρτέλες για ομαδοποίηση", "Πίνακας των όρων της διαίρεσης", "Φύλλο εργασίας"],
        "overview": "Οι μαθητές οργανώνουν αντικείμενα σε ίσες ομάδες, συνδέουν πηλίκο και υπόλοιπο με την πραγματική κατάσταση και διατυπώνουν τις συνθήκες της Ευκλείδειας διαίρεσης.",
        "formativeAssessment": ["Γράψε τη διαίρεση $23:4$ στη μορφή $\\Delta=\\delta\\cdot\\pi+\\upsilon$.", "Εξήγησε γιατί η ισότητα $29=6\\cdot3+11$ δεν αποτελεί Ευκλείδεια διαίρεση με διαιρέτη $6$.", "Πότε λέμε ότι ένας φυσικός αριθμός διαιρεί έναν άλλο;"],
        "exitTicket": ["Ποια είναι όλα τα δυνατά υπόλοιπα σε διαίρεση με διαιρέτη $5$;", "Αν $\\Delta=9\\cdot7+4$, ονόμασε διαιρέτη, πηλίκο και υπόλοιπο.", "Βαθμολόγησε τη βεβαιότητά σου από $1$ έως $4$ και σημείωσε τι χρειάζεται επανάληψη."],
    })
