def _polish_g7_a2_1(lesson):
    """Hand-audited introduction to fractions."""
    if lesson["id"] != "g7-a2-1":
        return

    lesson["theory"] = [
        "Το κλάσμα $\\frac{\\alpha}{\\beta}$, με $\\beta\\ne0$, μπορεί να εκφράζει μέρος ενός όλου που έχει χωριστεί σε $\\beta$ ίσα μέρη. Ο παρονομαστής $\\beta$ δείχνει σε πόσα ίσα μέρη χωρίστηκε το όλο και ο αριθμητής $\\alpha$ πόσα από αυτά παίρνουμε.",
        "Το κλάσμα εκφράζει επίσης το πηλίκο της διαίρεσης $\\alpha: \\beta$. Για παράδειγμα, αν $3$ πίτσες μοιραστούν εξίσου σε $4$ παιδιά, κάθε παιδί παίρνει $\\frac34$ πίτσας.",
        "Το $\\frac{\\alpha}{\\beta}$ είναι αριθμός και έχει συγκεκριμένη θέση στην αριθμογραμμή. Η μονάδα χωρίζεται σε $\\beta$ ίσα διαστήματα και μετράμε $\\alpha$ τέτοια διαστήματα από το $0$.",
        "Αν $\\alpha<\\beta$, το κλάσμα είναι μικρότερο από $1$. Αν $\\alpha=\\beta$, ισούται με $1$. Αν $\\alpha>\\beta$, είναι μεγαλύτερο από $1$.",
        "Για $\\beta\\ne0$, ισχύει $\\frac0\\beta=0$ και $\\frac\\beta\\beta=1$. Παρονομαστής $0$ δεν επιτρέπεται, επειδή η διαίρεση με το $0$ δεν ορίζεται.",
    ]
    lesson["example"] = {
        "title": "Λυμένο παράδειγμα: Τρεις πίτσες σε τέσσερα παιδιά",
        "text": "Μοιράζουμε $3$ ίδιες πίτσες εξίσου σε $4$ παιδιά. Χωρίζουμε κάθε πίτσα σε $4$ ίσα μέρη. Δημιουργούνται $12$ τέταρτα και κάθε παιδί παίρνει $3$ τέταρτα. Άρα η μερίδα του είναι $\\frac34$ πίτσας. Το ίδιο αποτέλεσμα δίνει η διαίρεση $3:4=\\frac34$.",
    }
    lesson["plan"].update({
        "objectives": ["Να αναγνωρίζει το κλάσμα ως μέρος ίσων μερών, ως πηλίκο και ως αριθμό.", "Να διακρίνει τον ρόλο αριθμητή και παρονομαστή.", "Να αναπαριστά απλά κλάσματα με σχήμα και στην αριθμογραμμή.", "Να συγκρίνει ένα κλάσμα με τη μονάδα από τη σχέση αριθμητή και παρονομαστή."],
        "prerequisites": ["Ισομερής διανομή", "Διαίρεση φυσικών αριθμών", "Αριθμογραμμή"],
        "duration": "50 λεπτά",
        "materials": ["Χάρτινοι κύκλοι ή λωρίδες", "Αριθμογραμμή", "Χρωματιστά μολύβια", "Φύλλο εργασίας"],
        "overview": "Οι μαθητές συνδέουν τρεις αναπαραστάσεις του ίδιου κλάσματος: ισομερής διανομή, μέρος ενός όλου και θέση στην αριθμογραμμή.",
        "formativeAssessment": ["Σχεδίασε δύο διαφορετικά σχήματα που παριστάνουν το $\\frac34$.", "Πού βρίσκεται το $\\frac54$ σε σχέση με το $1$; Αιτιολόγησε.", "Τι σημαίνει το $3:4$ σε ένα πρόβλημα μοιρασιάς;"],
        "exitTicket": ["Τοποθέτησε το $\\frac32$ στην αριθμογραμμή.", "Εξήγησε με μία πρόταση γιατί το $\\frac37<1$.", "Γράψε ένα δικό σου πρόβλημα που έχει απάντηση $\\frac25$."],
    })
    lesson["attention"] = ["Τα μέρη πρέπει να είναι ίσα· διαφορετικά το χρωματισμένο τμήμα δεν περιγράφεται σωστά από το κλάσμα.", "Ο παρονομαστής δείχνει το πλήθος των ίσων μερών της μονάδας, όχι το μέγεθος του χρωματισμένου μέρους.", "Το κλάσμα είναι αριθμός και μπορεί να είναι μεγαλύτερο από $1$.", "Το $\\frac0\\beta$ ορίζεται για $\\beta\\ne0$, ενώ κανένα κλάσμα με παρονομαστή $0$ δεν ορίζεται."]
    lesson["worksheet"] = {
        "A": ["Ένα ορθογώνιο χωρίζεται σε $8$ ίσα μέρη και χρωματίζονται τα $3$. Γράψε το κλάσμα και ονόμασε αριθμητή και παρονομαστή.", "Χαρακτήρισε τα $\\frac27,\\frac77,\\frac97$ ως μικρότερο, ίσο ή μεγαλύτερο από $1$."],
        "B": ["Τρεις ίδιες σοκολάτες μοιράζονται εξίσου σε $5$ παιδιά. Τι μέρος μιας σοκολάτας παίρνει κάθε παιδί;", "Σημείωσε τα $\\frac14,\\frac34,\\frac54$ σε αριθμογραμμή από το $0$ έως το $2$."],
        "C": ["Βρες όλα τα κλάσματα με παρονομαστή $6$, αριθμητή φυσικό μικρότερο από $10$ και τιμή μεγαλύτερη από $1$.", "Δώσε δύο διαφορετικές ιστορίες μοιρασιάς που οδηγούν στο κλάσμα $\\frac23$."],
    }
    lesson["solutions"] = [
        {"title": "Επίπεδο Α", "text": "1) $\\frac38$: αριθμητής $3$, παρονομαστής $8$. 2) $\\frac27<1$, $\\frac77=1$, $\\frac97>1$."},
        {"title": "Επίπεδο Β", "text": "1) Κάθε παιδί παίρνει $\\frac35$ σοκολάτας. 2) Χωρίζουμε κάθε μονάδα σε τέσσερα ίσα διαστήματα: $\\frac14$ και $\\frac34$ πριν από το $1$, $\\frac54$ ένα τέταρτο μετά το $1$."},
        {"title": "Επίπεδο Γ", "text": "1) $\\frac76,\\frac86,\\frac96$. 2) Ενδεικτικά: δύο πίτσες σε τρία παιδιά ή δύο λίτρα χυμού σε τρία ίσα δοχεία."},
    ]
    lesson["recap"] = {"keyPoints": ["Το κλάσμα περιγράφει ίσα μέρη, πηλίκο και θέση στην αριθμογραμμή.", "Ο αριθμητής δείχνει πόσα ίσα μέρη παίρνουμε και ο παρονομαστής σε πόσα ίσα μέρη χωρίζεται η μονάδα.", "$\\frac{\\alpha}{\\beta}=\\alpha:\\beta$, με $\\beta\\ne0$.", "Η σύγκριση αριθμητή και παρονομαστή δείχνει αν το κλάσμα είναι μικρότερο, ίσο ή μεγαλύτερο από $1$.", "Κλάσμα με παρονομαστή $0$ δεν ορίζεται."], "nextLessonIds": ["g7-a2-2"], "furtherStudy": ["Διερεύνησε με σχήματα γιατί τα $\\frac12,\\frac24,\\frac36$ παριστάνουν τον ίδιο αριθμό."]}
    lesson["guidedPractice"] = {"prompt": "Δύο ίδιες πίτσες μοιράζονται εξίσου σε $3$ παιδιά. Τι μέρος μιας πίτσας παίρνει κάθε παιδί; Παράστησέ το και στην αριθμογραμμή.", "hint": "Χώρισε κάθε πίτσα σε $3$ ίσα μέρη και μέτρησε πόσα τρίτα παίρνει κάθε παιδί.", "solution": "Οι $2$ πίτσες δίνουν $6$ τρίτα. Κάθε παιδί παίρνει $2$ τρίτα, δηλαδή $\\frac23$ πίτσας. Στην αριθμογραμμή χωρίζουμε το $0$–$1$ σε τρία ίσα διαστήματα και σημειώνουμε το δεύτερο σημείο."}
    lesson["assessment"] = {"durationMinutes": 15, "questions": [
        Q("Σε σχήμα χωρισμένο σε $8$ ίσα μέρη έχουν χρωματιστεί τα $3$. Ποιο κλάσμα παριστάνεται;", ["$\\frac38$", "$\\frac83$", "$\\frac35$", "$\\frac18$"], 0, "Παίρνουμε $3$ από τα $8$ ίσα μέρη."),
        Q("Ποια διαίρεση εκφράζει το $\\frac47$;", ["$7:4$", "$4:7$", "$4\\cdot7$", "$7-4$"], 1, "$\\frac{\\alpha}{\\beta}=\\alpha:\\beta$."),
        Q("Ποιο κλάσμα είναι μεγαλύτερο από $1$;", ["$\\frac58$", "$\\frac88$", "$\\frac98$", "$\\frac08$"], 2, "Όταν ο αριθμητής είναι μεγαλύτερος από τον παρονομαστή, το κλάσμα είναι μεγαλύτερο από $1$."),
        Q("Τρεις πίτσες μοιράζονται εξίσου σε $5$ παιδιά. Πόση πίτσα παίρνει κάθε παιδί;", ["$\\frac53$", "$\\frac35$", "$\\frac15$", "$\\frac13$"], 1, "Η μερίδα είναι το πηλίκο $3:5=\\frac35$."),
        Q("Ποια πρόταση είναι σωστή;", ["$\\frac50=0$", "$\\frac05=5$", "$\\frac55=1$", "$\\frac57=1$"], 2, "Ίσος μη μηδενικός αριθμητής και παρονομαστής δίνουν μονάδα."),
        Q("Σε αριθμογραμμή χωρίζουμε τη μονάδα σε $4$ ίσα διαστήματα. Ποιο σημείο βρίσκεται αμέσως μετά το $1$;", ["$\\frac14$", "$\\frac34$", "$\\frac44$", "$\\frac54$"], 3, "$1=\\frac44$, άρα το επόμενο τέταρτο είναι $\\frac54$."),
    ]}

    by_id = {question["id"]: question for question in lesson["practiceQuestions"]}
    if "g7-a2-1-input" in by_id:
        by_id["g7-a2-1-input"].update({"prompt": "Απάντησε χωρίς επιλογές: Δύο πίτσες μοιράζονται εξίσου σε $3$ παιδιά. Τι κλάσμα πίτσας παίρνει κάθε παιδί;", "acceptedAnswers": ["2/3", "\\frac{2}{3}", "2⁄3"], "explanation": "$2:3=\\frac23$.", "hints": ["Γράψε τη μοιρασιά ως διαίρεση.", "Το πλήθος των πιτσών γίνεται αριθμητής και το πλήθος των παιδιών παρονομαστής."]})
    if "g7-a2-1-fill" in by_id:
        by_id["g7-a2-1-fill"].update({"prompt": "Συμπλήρωσε: Το κλάσμα $\\frac97$ είναι ___ από τη μονάδα.", "acceptedAnswers": ["μεγαλύτερο", "μεγαλυτερο"], "explanation": "$9>7$, άρα $\\frac97>1$.", "hints": ["Σύγκρινε αριθμητή και παρονομαστή."]})
    if "g7-a2-1-error" in by_id:
        by_id["g7-a2-1-error"].update({"prompt": "Ένας μαθητής χρωματίζει δύο άνισα τμήματα ενός σχήματος και γράφει $\\frac25$. Εντόπισε το λάθος.", "modelAnswer": "Για να παριστάνεται το $\\frac25$, το όλο πρέπει να έχει χωριστεί σε $5$ ίσα μέρη. Το πλήθος μόνο των τμημάτων δεν αρκεί.", "hints": ["Τι απαιτεί ο παρονομαστής $5$;", "Έλεγξε αν όλα τα μέρη έχουν το ίδιο μέγεθος."]})


