def _apply_geometry_personalization(lessons):
    by_id = {l["id"]: l for l in lessons}
    for lid, ov in GEOMETRY_OVERRIDES.items():
        l = by_id.get(lid)
        if not l:
            continue
        l["plan"]["overview"] = ov["overview"]
        l["plan"]["materials"] = ov["materials"]
        for i, desc in enumerate(ov["phase_descs"]):
            if i < len(l["plan"]["phases"]):
                l["plan"]["phases"][i]["description"] = desc
        l["plan"]["differentiation"]["support"] = ov["support"]
        l["plan"]["differentiation"]["challenge"] = ov["challenge"]
        l["recap"]["keyPoints"] = ov["recap"]
    return lessons


LESSONS = _apply_geometry_personalization(LESSONS)


