def _add_missing_geometry_mcq(lessons):
    by_id = {l["id"]: l for l in lessons}
    for lid, extra in EXTRA_MCQ.items():
        l = by_id.get(lid)
        if l is None:
            continue
        pq = l.get("practiceQuestions", [])
        # find index of the last plain mcq item (before input/fill/self-check/matching/ordering/recall)
        insert_at = 0
        for i, q in enumerate(pq):
            t = q.get("type") or "mcq"
            if t == "mcq" and "recall" not in q.get("id", ""):
                insert_at = i + 1
        new_q = dict(extra)
        new_q["id"] = f"{lid}-q-extra"
        new_q["skill"] = l["title"]
        new_q["difficulty"] = 1
        new_q["representation"] = "verbal"
        new_q["hints"] = [
            "Εντόπισε πρώτα τι δίνεται και τι ζητείται.",
            "Σύνδεσε τα δεδομένα με τον βασικό κανόνα του μαθήματος.",
        ]
        new_q["optionFeedback"] = [
            "" if i == new_q["correct"] else
            f"Η επιλογή «{new_q['options'][i]}» δεν συμφωνεί με τον κανόνα που χρειάζεται εδώ. Ξανασύνδεσε όσα δίνονται με αυτό που ζητείται."
            for i in range(len(new_q["options"]))
        ]
        pq.insert(insert_at, new_q)
        l["practiceQuestions"] = pq
        l["questionCount"] = len(pq)
    return lessons


LESSONS = _add_missing_geometry_mcq(LESSONS)


