def _build_g8_ch1_practice_questions(lid, data):
    mcqs = list(data["mcq"])
    if data.get("recall_prev"):
        prev_id, prompt, options, correct, explanation = data["recall_prev"]
        recall_q = AQ(f"{lid}-recall-{prev_id}", "Ανάκληση προηγούμενου μαθήματος", 1,
                       prompt, options, correct, explanation,
                       ["Ανακάλεσε τι έμαθες στο προηγούμενο μάθημα.", "Εφάρμοσε τον ίδιο κανόνα."],
                       ["" if i == correct else "Ξαναδές το προηγούμενο μάθημα για αυτόν τον κανόνα." for i in range(len(options))])
        mcqs = mcqs[:5] + [recall_q]

    pq = list(mcqs)
    pq.append({
        "id": f"{lid}-input", "type": "input", "skill": lid, "difficulty": 2,
        "representation": "constructed-response",
        "prompt": data["input_prompt"], "acceptedAnswers": [data["input_answer"]],
        "explanation": data["input_explanation"],
        "hints": ["Λύσε βήμα-βήμα.", "Έλεγξε την πράξη πριν απαντήσεις."],
    })
    pq.append({
        "id": f"{lid}-fill", "type": "fill", "skill": lid, "difficulty": 2,
        "representation": "verbal",
        "prompt": data["fill_prompt"], "acceptedAnswers": [data["fill_answer"]],
        "explanation": data["fill_explanation"],
        "hints": ["Σκέψου ποιο βήμα λείπει.", "Έλεγξε το αποτέλεσμα."],
    })
    pq.append({
        "id": f"{lid}-error", "type": "self-check", "activityKind": "error-correction",
        "skill": lid, "difficulty": 3, "representation": "error-analysis",
        "prompt": data["error_prompt"], "modelAnswer": data["error_answer"],
        "hints": ["Ξαναδιάβασε προσεκτικά τι υποστηρίζει ο μαθητής.", "Σύγκρινε με τον σωστό κανόνα."],
    })
    pq.append({
        "id": f"{lid}-investigation", "type": "self-check", "activityKind": "transfer",
        "skill": lid, "difficulty": 3, "representation": "application",
        "prompt": data["investigation_prompt"], "modelAnswer": data["investigation_answer"],
        "hints": ["Οργάνωσε τα δεδομένα πριν ξεκινήσεις.", "Έλεγξε τη λύση σου στο τέλος."],
    })
    pq.append({
        "id": f"{lid}-matching", "type": "matching", "skill": lid, "difficulty": 2,
        "representation": "multiple-representation",
        "prompt": "Αντιστοίχισε κάθε ερώτημα με τη σωστή απάντηση.",
        "pairs": data["matching_pairs"],
        "explanation": "Κάθε ζεύγος συνδέει το ερώτημα με το αποτέλεσμα του αντίστοιχου κανόνα.",
        "hints": ["Λύσε κάθε ερώτημα χωριστά πριν αντιστοιχίσεις.", "Κάθε απάντηση χρησιμοποιείται μία φορά."],
    })
    pq.append({
        "id": f"{lid}-ordering", "type": "ordering", "skill": lid, "difficulty": 2,
        "representation": "procedural",
        "prompt": data["ordering_prompt"], "steps": data["ordering_steps"],
        "explanation": "Η σωστή σειρά ακολουθεί τη λογική ροή επίλυσης.",
        "hints": ["Σκέψου τι πρέπει να γίνει πρώτο.", "Ο έλεγχος γίνεται πάντα τελευταίος."],
    })
    return pq


def _apply_g8_chapter1_practice(lessons):
    by_id = {l["id"]: l for l in lessons}
    for lid, data in G8_CH1_PRACTICE.items():
        l = by_id.get(lid)
        if l is None:
            continue
        pq = _build_g8_ch1_practice_questions(lid, data)
        l["practiceQuestions"] = pq
        l["questionCount"] = len(pq)
        gp = GUIDED_PRACTICE.get(lid)
        if gp:
            l["guidedPractice"] = gp
        l["learningSpecification"] = {
            "flow": ["ανάκληση", "λυμένο παράδειγμα", "καθοδηγούμενη εφαρμογή", "ανεξάρτητη εξάσκηση", "επανάληψη"],
            "masteryRequiresRepeatedSuccess": True,
            "secondAttemptWeight": 0.6,
        }
    return lessons


LESSONS = _apply_g8_chapter1_practice(LESSONS)


