def _apply_g8_chapter3_practice(lessons):
    by_id = {l["id"]: l for l in lessons}
    for lid, data in G8_CH3_PRACTICE.items():
        l = by_id.get(lid)
        if l is None:
            continue
        pq = _build_g8_ch1_practice_questions(lid, data)
        l["practiceQuestions"] = pq
        l["questionCount"] = len(pq)
        gp = GUIDED_PRACTICE_CH3.get(lid)
        if gp:
            l["guidedPractice"] = gp
        l["learningSpecification"] = {
            "flow": ["ανάκληση", "λυμένο παράδειγμα", "καθοδηγούμενη εφαρμογή", "ανεξάρτητη εξάσκηση", "επανάληψη"],
            "masteryRequiresRepeatedSuccess": True,
            "secondAttemptWeight": 0.6,
        }
    return lessons


LESSONS = _apply_g8_chapter3_practice(LESSONS)


