def _apply_g8_b1_figure_mapping(lessons):
    by_id = {l["id"]: l for l in lessons}
    for lid, figs in G8_B1_FIGURE_MAPPING.items():
        l = by_id.get(lid)
        if l is not None:
            l["figures"] = figs
    return lessons


