def _apply_g9_chaptera2_practice(lessons):
    by_id = {l["id"]: l for l in lessons}
    for lid, data in G9_CHA2_PRACTICE.items():
        l = by_id.get(lid)
        if l is None:
            continue
        pq = _build_g8_ch1_practice_questions(lid, data)
        l["practiceQuestions"] = pq
        l["questionCount"] = len(pq)
        gp = GUIDED_PRACTICE_G9A2.get(lid)
        if gp:
            l["guidedPractice"] = gp
        l["learningSpecification"] = {
            "flow": ["ανάκληση", "λυμένο παράδειγμα", "καθοδηγούμενη εφαρμογή", "ανεξάρτητη εξάσκηση", "επανάληψη"],
            "masteryRequiresRepeatedSuccess": True,
            "secondAttemptWeight": 0.6,
        }
    return lessons


LESSONS = _apply_g9_chaptera2_practice(LESSONS)


def all_docs():
    return GRADES, LESSONS


def all_books():
    return BOOKS
